formulas.expression:
IF(
  {!LoopCriaDestinosCoordenada.IsCoordenada},
  VALUE(
    TRIM(
      LEFT(
        {!LoopCriaDestinosCoordenada.formattedValue},
        FIND(",", {!LoopCriaDestinosCoordenada.formattedValue}) - 1
      )
    )
  ),
  null
)

IF(
  {!LoopCriaDestinosCoordenada.IsCoordenada},
  VALUE(
    TRIM(
      RIGHT(
        {!LoopCriaDestinosCoordenada.formattedValue},
        LEN({!LoopCriaDestinosCoordenada.formattedValue}) - FIND(",", {!LoopCriaDestinosCoordenada.formattedValue})
      )
    )
  ),
  null
)

IF(
  AND(
    {!TipoProduto} = 'Charter',
    {!LocalOrigemWrapper.IsCoordenada}
  ),
  VALUE(
    TRIM(
      LEFT(
        {!LocalOrigemWrapper.formattedValue},
        FIND(",", {!LocalOrigemWrapper.formattedValue}) - 1
      )
    )
  ),
  null
)

IF(
  AND(
    {!TipoProduto} = 'Charter',
    {!LocalOrigemWrapper.IsCoordenada}
  ),
  VALUE(
    TRIM(
      RIGHT(
        {!LocalOrigemWrapper.formattedValue},
        LEN({!LocalOrigemWrapper.formattedValue}) - FIND(",", {!LocalOrigemWrapper.formattedValue})
      )
    )
  ),
  null
)
